insert into public.stories (user_id, date, data) select id, '2026-10-21', '{"createdAt": 1792542052581, "date": "2026-10-21", "kanjiKnown": 40, "level": 2, "sentences": [{"en": "Today is Sunday.", "jp": "{今日|きょう}は{日|にち}よう{日|び}です。"}, {"en": "Mr. Tanaka goes to the market with a girl.", "jp": "{田|た}なかさんは{女|おんな}の{子|こ}と{市|いち}ばに{行|い}きます。"}, {"en": "There were big tomatoes at the entrance.", "jp": "{入|い}り{口|ぐち}に{大|おお}きいトマトがありました。"}, {"en": "The girl said, \"I want to buy one.\"", "jp": "{女|おんな}の{子|こ}は「{一|ひと}つ{買|か}いたいです」と{言|い}いました。"}, {"en": "The tomatoes are 60 yen each.", "jp": "トマトは{一|ひと}つ{六十|ろくじゅう}{円|えん}です。"}, {"en": "Mr. Tanaka bought three.", "jp": "{田|た}なかさんは{三|みっ}つ{買|か}いました。"}, {"en": "The girl held the bag in her small hands.", "jp": "{女|おんな}の{子|こ}は{小|ちい}さい{手|て}でふくろを{持|も}ちました。"}, {"en": "Because many people were inside, the two of them walked slowly to the exit.", "jp": "{人|ひと}がたくさん{入|はい}っているので、{二|ふた}人は{出口|でぐち}までゆっくり{歩|ある}きました。"}, {"en": "After going out, the two ate a little of the tomatoes.", "jp": "{出|で}てから、{二|ふた}人はトマトを{少|すこ}し{食|た}べました。"}, {"en": "They were very delicious.", "jp": "とてもおいしかったです。"}, {"en": "They will come again next week.", "jp": "{来|らい}しゅうもまた{来|き}ます。"}], "title": "{今日|きょう}の{市|いち}ばんで", "titleEn": "At the Market Today", "words": [{"meaning": "market", "reading": "いちば", "word": "市場"}, {"meaning": "to buy", "reading": "かう", "word": "買う"}, {"meaning": "to say", "reading": "いう", "word": "言う"}, {"meaning": "to hold, carry", "reading": "もつ", "word": "持つ"}, {"meaning": "to walk", "reading": "あるく", "word": "歩く"}, {"meaning": "to eat", "reading": "たべる", "word": "食べる"}, {"meaning": "to come", "reading": "くる", "word": "来る"}, {"meaning": "exit", "reading": "でぐち", "word": "出口"}], "wordsKnown": 10}'::jsonb from me
insert into public.stories (user_id, date, data) select id, '2026-10-25', '{"createdAt": 1792889703157, "date": "2026-10-25", "kanjiKnown": 40, "level": 2, "sentences": [{"en": "Today is October 25th.", "jp": "{今日|きょう}は{十月|じゅうがつ}にじゅうごにちです。"}, {"en": "I went to a big park.", "jp": "{大|おお}きい{公園|こうえん}に{行|い}きました。"}, {"en": "There were many people in the park.", "jp": "{公園|こうえん}の{中|なか}に{人々|ひとびと}がたくさんいました。"}, {"en": "A girl is playing with three balls.", "jp": "{女|おんな}の{子|こ}が{三|みっ}つのボールで{遊|あそ}んでいます。"}, {"en": "A boy climbs up a mountain-shaped slide.", "jp": "{男|おとこ}の{子|こ}は{山|やま}の{形|かたち}のすべり{台|だい}に{上|のぼ}ります。"}, {"en": "When he got to the top, he laughed in a loud voice.", "jp": "{上|うえ}まで{上|あが}ると、{大|おお}きいこえで{笑|わら}いました。"}, {"en": "I took out a rice ball under a tree.", "jp": "わたしは{木|き}の{下|した}でおにぎりを{出|だ}しました。"}, {"en": "A small dog is sleeping under the same tree.", "jp": "{同|おな}じ{木|き}の{下|した}で、{小|ちい}さい{犬|いぬ}がねています。"}, {"en": "The sun is out, and it feels nice.", "jp": "{日|ひ}ざしがあって、{気持|きも}ちがいいです。"}, {"en": "Five minutes later, my friend came.", "jp": "{五|ご}{分|ふん}あとに、{友|とも}だちが{来|き}ました。"}, {"en": "We shared the rice ball and ate it together.", "jp": "いっしょにおにぎりを{分|わ}けて{食|た}べました。"}, {"en": "Forgetting my busy daily life, it was a good day.", "jp": "{日々|ひび}のいそがしさをわすれて、いい{一日|いちにち}でした。"}], "title": "{日曜日|にちようび}の{公園|こうえん}", "titleEn": "Sunday at the Park", "words": [{"meaning": "park", "reading": "こうえん", "word": "公園"}, {"meaning": "to play", "reading": "あそぶ", "word": "遊ぶ"}, {"meaning": "to laugh", "reading": "わらう", "word": "笑う"}, {"meaning": "tree", "reading": "き", "word": "木"}, {"meaning": "dog", "reading": "いぬ", "word": "犬"}, {"meaning": "friend", "reading": "ともだち", "word": "友だち"}, {"meaning": "feeling", "reading": "きもち", "word": "気持ち"}, {"meaning": "to eat", "reading": "たべる", "word": "食べる"}], "wordsKnown": 25}'::jsonb from me
insert into public.hooks (id, kanji, text) values
  ('u4e00', '一', 'A single horizontal stroke, like **one** finger held sideways.'),
  ('u4e09', '三', 'Three horizontal lines with the middle one shortest: **three**.'),
  ('u4e0a', '上', 'A stick rising from the ground line, pointing **up**. Its opposite 下 hangs down below the line.'),
  ('u4e2d', '中', 'A box (口) skewered by one line straight through the **middle**.'),
  ('u4e5d', '九', 'Looks like 力, but the right stroke curls outward into a tail. A cat curling its tail around the number **nine**.'),
  ('u4e8c', '二', 'Two horizontal lines, the bottom one longer: **two**.'),
  ('u4e94', '五', '二 with a zigzag squeezed between its lines, making a small box in the middle: **five**.'),
  ('u4eba', '人', 'Two strokes leaning together like walking legs: a **person** striding along. In 入 (enter) the right stroke sits on top instead.'),
  ('u5165', '入', '人 flipped: the right stroke is on top and the left one slides in underneath, like ducking through a doorway to **enter**.'),
  ('u51fa', '出', 'Two 山 (mountain) shapes stacked, one poking up over the other to get **out**. An exit sign in kanji.'),
  ('u5206', '分', '八 (two strokes splitting apart) over 刀 (a **sword**): the blade **divides** something in two. Also used for minutes.'),
  ('u529b', '力', 'A flexed arm: the hooked stroke is the bicep, the slash is the forearm. **Power**! Unlike 九, the right side drops straight down with no curl.'),
  ('u5341', '十', 'A plus sign, one line across and one down. Cross your two hands, all **ten** fingers out.'),
  ('u5927', '大', 'A 人 (person) with arms stretched wide across the top, showing you how **big** the fish was.'),
  ('u5b50', '子', 'A swaddled baby: a hook for the body, one line across for little arms. A **child**.'),
  ('u624b', '手', 'Picture 手 as a **hand** with a long wrist: three horizontal lines are fingers, and one vertical stroke curving at the bottom is the arm. Imagine a waving **hand** reaching up from a sleeve, fingers spread, to grab the **て** (te) of a friend and shake it.'),
  ('u65e5', '日', 'A box with one line across the middle, a window with the **sun** shining in. 目 (eye) is taller, with two lines inside.'),
  ('u6708', '月', 'Like 日 but open at the bottom, with a sweeping left leg and two lines inside: a crescent **moon** hanging in its frame. It also means month.'),
  ('u672c', '本', '木 (tree) with a short line marking the base of the trunk: the **root** or origin. Trees also become paper, so it means **book**.'),
  ('u76ee', '目', 'Picture a tall **eye** turned sideways: the outer box is the eye socket, and the two short bars inside are the pupil and eyelid lines. A sleepy giant stacks two pancakes in his socket to hide his tired **eye**, so he can''t **look** at anyone.')
